// ---- bottom navigation ---------------------------------------------------------
// Overlay flow stacks children: the glow layer paints the deep-space ground
// beneath the plain Down column of body + glass navbar. Nav marks are native
// glyph tiles (the same language as the agent squad): runtime SVG rasterises
// blank in this stack, CJK glyphs never do. Tabs centre via the Fill-Fit-Fill
// row — full-width on a phone, centred cluster on a desktop.
fn nav_tab(label, glyph, target, badge){
    GestureView{width: Fit height: Fit padding: Inset{top: 7 bottom: 7 left: 16 right: 16} on_tap: |x, y| go(target)
        View{width: Fit height: Fit flow: Down spacing: 4 align: Align{x: 0.5}
            if screen == target {
                RoundedView{width: 24 height: 2 draw_bg +: {g1: violet g2: cyan border_radius: 1.0}}
            } else {
                View{width: 24 height: 2}
            }
            View{width: Fit height: Fit flow: Overlay
                RoundedView{width: 32 height: 32 draw_bg +: {color: pick(screen == target, #x170f31, #x00000000) border_radius: 11.0 border_size: 1.0 border_color: pick(screen == target, violet, line2)} align: Align{x: 0.5 y: 0.5}
                    Label{text: glyph draw_text.color: pick(screen == target, violetHi, #x6c6b6d) draw_text.text_style.font_size: 13}}
                if badge != "" {
                    View{width: Fill height: Fill align: Align{x: 1.0 y: 0.0}
                        RoundedView{width: 14 height: 14 draw_bg +: {color: violet border_radius: 7.0} align: Align{x: 0.5 y: 0.5}
                            Label{text: badge draw_text.color: #xffffffff draw_text.text_style.font_size: 8}
                        }
                    }
                }
            }
            Label{text: label draw_text.color: pick(screen == target, violetHi, #x6c6b6d) draw_text.text_style.font_size: 10}
        }
    }
}

